  R1 N004 0 4k
  xma4 Vbiasp N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma4} l={L_xma4}
  xma3 N001 N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma3} l={L_xma3}
  xm5 N001 N003 0 0 sky130_fd_pr__nfet_01v8 w={W_xm5} l={L_xm5}
  xm7 VDD Vbiasp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm7} l={L_xm7}
  xm2 Vbiasp Vbiasn 0 0 sky130_fd_pr__nfet_01v8 w={W_xm2} l={L_xm2}
  xm6 N003 N003 N004 0 sky130_fd_pr__nfet_01v8 w={W_xm6} l={L_xm6}
.ends SUB_1
* --- DUT Netlist End ---

* Input Sources
V_vip vip 0 dc 0.5 ac 0
V_vim vim 0 dc 0.5 ac 1 pulse(0.6 0.4 75n 100p 100p 5n 10n)

.control
* 1. DC Operating Point
op
let power = -i(VDD) * 1.8
let vout_diff_dc = v(vop) - v(vom)
let vm_dc = v(vm)
print power vout_diff_dc vm_dc

* 2. AC Analysis (Extracting Open-Loop Gain from Closed-Loop setup)
ac dec 100 1 1G
let vout_diff = v(vop) - v(vom)
let vin_diff = v(vp) - v(vm)
let A_OL = vout_diff / vin_diff
let A_OL_db = 20 * log10(mag(A_OL))
meas ac A_OL_DC find A_OL_db at=1
meas ac f_un when A_OL_db=0 fall=1

* 3. Transient Analysis (Matching Fig 26.48)
tran 100p 90n 70n
let vout_diff_tran = v(vop) - v(vom)
meas tran vout_diff_max max vout_diff_tran
meas tran vout_diff_min min vout_diff_tran
.endc

.end

